(()=>{const dialog=document.querySelector('.guide-loader-dialog'),open=document.querySelector('[data-loader-preview]'),close=dialog.querySelector('.guide-dialog-close');open.addEventListener('click',()=>dialog.showModal());close.addEventListener('click',()=>dialog.close());dialog.addEventListener('click',event=>{if(event.target!==dialog)return;const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close()});dialog.addEventListener('close',()=>open.focus({preventScroll:true}));})();
